from lesson_authoring import entry as E
W=[
E('decathlon','英 /dɪˈkæθlɒn/；美 /dɪˈkæθlɑːn/','十项全能','同一个运动员不能只会跑，还要在跳、投等十个项目中综合较量。','deca- 十 + 希腊 athlon 比赛、奖赏；借古典构件为现代综合项目命名。',[['希腊 deka + athlon','十 + 比赛'],['现代体育造词 decathlon','由十个项目组成的全能比赛']],'标准田径十项全能把跑、跳、投等十个项目的表现换成分数，再累加比较。它不是十个人组队，也不是同一比赛重复十次。首字母大写时还可能是品牌名，要按语境区别。','compete in the decathlon；a decathlon champion；a decathlon score。','decathlon 十项全能；triathlon 铁人三项。数字前缀告诉你项目数，不告诉你每个项目具体是什么。',('He trained for the decathlon by improving his jumping and throwing.','他通过提高跳跃和投掷能力，为十项全能比赛训练。'),('The decathlon tests a wide range of athletic skills.','十项全能考验多方面的运动技能。'),sources=['https://www.etymonline.com/word/decathlon','https://worldathletics.org/disciplines/combinedevents/decathlon']),
E('decathlete','英 /diːˈkæθliːt/；美 /diːˈkæθliːt/','十项全能运动员','站在十个项目起点上的，是同一位全能选手。','dec- 十 + athlete 运动员，与 decathlon 项目名配套；-athlete 指人，-athlon 指比赛。',[['希腊 deka 与 athlete 的古典构件','十 + 运动员'],['英语 dec- + athlete → decathlete','参加十项全能的人']],'a decathlete 是运动员身份，不等于他已拿冠军，也不意味着十项都同样强。这个词和 athlete 一样说人，所以可以直接说 a young decathlete、several decathletes。','a professional decathlete；a former decathlete；train as a decathlete。','decathlete 是人，decathlon 是项目。不要用 He is a decathlon 表示他是十项全能选手。',('The young decathlete set a personal best in the long jump.','这位年轻的十项全能选手在跳远项目中创造了个人最好成绩。'),('A decathlete must balance training across several disciplines.','十项全能选手必须兼顾多个项目的训练。'),sources=['https://en.wiktionary.org/wiki/decathlete','https://worldathletics.org/disciplines/combinedevents/decathlon']),
E('decapod','英 /ˈdekəpɒd/；美 /ˈdekəpɑːd/','十足目动物，如虾、蟹、龙虾','看到十条步足这个身体特征，就能认出名字的两半。','deca- 十 + -pod 足，经法语 décapode 借入；这里的 pod 不是豆荚。',[['希腊 deka + pous，词干 pod-','十 + 足'],['法语 décapode → 英语 decapod','十足的 → 十足目动物']],'常见用法指虾、蟹、龙虾所在的十足目。名称中的十条步足包含某些已经变成螯的附肢，不是只数外观像走路腿的部分。它是动物分类词，不是任何恰好有十根突起的物体。','a decapod crustacean；decapod species；the anatomy of a decapod。','decapod 的 -pod 指足；decathlon 的 -athlon 指比赛。两词只有“十”这部分意义相同。',('A lobster is a decapod crustacean.','龙虾是一种十足目甲壳动物。'),('The class compared the body structures of several decapods.','课堂上比较了几种十足目动物的身体结构。'),sources=['https://en.wiktionary.org/wiki/decapod','https://www.merriam-webster.com/dictionary/decapod'])]
